do $guard$ begin
if (select count(*) from public.safety_spots where facility_type='aed' and active and not duplicate_candidate)<>43904 then raise exception 'baseline changed'; end if;
if (select count(*) from low_precision t join public.safety_spots p using(source_key) where p.facility_type='aed' and p.active and not p.duplicate_candidate and abs(p.latitude-t.latitude)<1e-7 and abs(p.longitude-t.longitude)<1e-7)<>306 then raise exception 'target changed'; end if;
end $guard$;
update public.safety_spots p set active=false,quality_status='rough' from low_precision t where p.source_key=t.source_key;
update public.safety_spots_nationwide_stage s set review_decision='hold',review_reason='開発12: 保存済み位置照合結果で町域等の代表点と公開座標が一致。施設座標の精度不足で公開保留',review_next_action='公式施設座標または位置情報point.level=8を確認して再審査',reviewed_at=now() from low_precision t where s.source_key=t.source_key;
do $guard$ begin
if (select count(*) from low_precision t join public.safety_spots p using(source_key) where p.active)<>0 then raise exception 'still active'; end if;
if (select count(*) from public.safety_spots where facility_type='aed' and active and not duplicate_candidate)<>43598 then raise exception 'post count'; end if;
end $guard$;
select 306 as held,(select count(*) from public.safety_spots where facility_type='aed' and active and not duplicate_candidate) as public_aed;
commit;
